(32296, 'Luke 12:58', 'Luke', 12, 58, 'کله چې له خپل مدعي سره قاضي ته ځئ، نو په لاره کې کوښښ وکړئ چې د هغه سره روغه وکړئ. که نه، نو هغه به مو قاضي ته راکاږي او قاضي به تاسو پولیس ته وسپاري او په زندان کې به واچول شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke12_verse_58.mp3', '', 1761754199, 1761754199),
(32297, 'Luke 12:59', 'Luke', 12, 59, 'زه تاسو ته وایم چې تر هغې پورې به له زندان څخه راخلاص نه شئ چې ترڅو پورې مو د خپل پور یوه یوه پیسه نه وي ورکړې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke12_verse_59.mp3', '', 1761754199, 1761754199),
(32298, 'John 11:1', 'John', 11, 1, 'د ایلعازر په نوم یو سړی ؤ چې ناروغه ؤ. د هغه کور په بیت‌عنیا کې ؤ، یعنې په هغه کلي کې چې مریم او د هغې خور مرتا اوسېدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_1.mp3', '', 1761754199, 1761754199),
(32299, 'John 11:2', 'John', 11, 2, 'دا هغه مریم ده چې ورسته د عیسی په پښو باندې عطر اچوي او د هغه پښې په خپلو ویښتانو وچوي. د هغې ورور ایلعازر ناروغه ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_2.mp3', '', 1761754199, 1761754199),
(32300, 'John 11:3', 'John', 11, 3, 'نو خویندو یې عیسی ته خبر ورولېږه او ورته ویې ویل: «استاذه، ستا ګران دوست ناروغه دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_3.mp3', '', 1761754199, 1761754199),
(32301, 'John 11:4', 'John', 11, 4, 'کله چې عیسی دا واورېدل نو ویې ویل: «ایلعازر به د دې ناروغۍ څخه نه مړ کیږي بلکې دا د خدای د جلال ښکاره کولو دپاره یوه وسیله ده، ترڅو د خدای زوی هم له دې لارې جلال ومومي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_4.mp3', '', 1761754199, 1761754199),
(32302, 'John 11:5', 'John', 11, 5, 'په عیسی باندې مرتا، د هغې خور او ایلعازر ګران وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_5.mp3', '', 1761754199, 1761754199),
(32303, 'John 11:6', 'John', 11, 6, 'سره له دې چې هغه د ایلعازر د ناروغۍ نه خبر شو، خو دوه ورځې نور هم په هغه ځای کې چې ؤ، هلته پاتې شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_6.mp3', '', 1761754199, 1761754199),
(32304, 'John 11:7', 'John', 11, 7, 'بیا هغه خپلو شاګردانو ته وویل: «راځئ چې بېرته یهودیې ته لاړ شو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_7.mp3', '', 1761754199, 1761754199),
(32305, 'John 11:8', 'John', 11, 8, 'شاګردانو ورته وویل: «ای استاذه، لږه موده مخکې د هغه ځای خلکو غوښتل تا سنګسار کړي، خو ته بیاهم غواړې چې هلته لاړ شې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_8.mp3', '', 1761754199, 1761754199),
(32306, 'John 11:9', 'John', 11, 9, 'عیسی ځواب ورکړ: «ایا په ورځ کې دولس ساعته رڼا نه وي؟ څوک چې د ورځې ګرځي نه راغورځیږي، ځکه چې د دې نړۍ رڼا ویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_9.mp3', '', 1761754199, 1761754199),
(32307, 'John 11:10', 'John', 11, 10, 'خو که څوک د شپې ګرځي نو غورځیږي، ځکه چې د هغه سره رڼا نه وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_10.mp3', '', 1761754199, 1761754199),
(32308, 'John 11:11', 'John', 11, 11, 'عیسی دا خبرې وکړې او بیا یې هغوی ته وویل: «زمونږ دوست ایلعازر ویده پروت دی، خو زه ورځم چې راویښ یې کړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_11.mp3', '', 1761754199, 1761754199),
(32309, 'John 11:12', 'John', 11, 12, 'شاګردانو وویل: «ای استاذه، که هغه ویده وي نو هغه به راپاڅیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_12.mp3', '', 1761754199, 1761754199),
(32310, 'John 11:13', 'John', 11, 13, 'خو د عیسی د خبرې مقصد دا ؤ چې ایلعازر مړ شوی دی، خو هغوی فکر وکړ چې د هغه مقصد عادي خوب دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_13.mp3', '', 1761754199, 1761754199);